1: package repair
2: 
3: import "sort"
4: 
5: type Request struct {
6: 	ID               string
7: 	Min, Max, Weight int
8: }
9: type quotaShare struct {
10: 	index, whole int
11: 	remainder    int64
12: }
13: 
14: func AllocateQuota(capacity int, requests []Request) (map[string]int, bool) {
15: 	if capacity < 0 {
16: 		return nil, false
17: 	}
18: 	out := map[string]int{}
19: 	minTotal, maxTotal := 0, 0
20: 	for _, request := range requests {
21: 		if request.ID == "" || request.Min < 0 || request.Max < request.Min || request.Weight <= 0 {
22: 			return nil, false
23: 		}
24: 		if _, exists := out[request.ID]; exists {
25: 			return nil, false
26: 		}
27: 		if minTotal > int(^uint(0)>>1)-request.Min || maxTotal > int(^uint(0)>>1)-request.Max {
28: 			return nil, false
29: 		}
30: 		minTotal += request.Min
31: 		maxTotal += request.Max
32: 		out[request.ID] = request.Min
33: 	}
34: 	if capacity < minTotal || capacity > maxTotal {
35: 		return nil, false
36: 	}
37: 	left := capacity - minTotal
38: 	for left > 0 {
39: 		weightTotal := int64(0)
40: 		active := []int{}
41: 		for i, request := range requests {
42: 			if out[request.ID] < request.Max {
43: 				weightTotal += int64(request.Weight)
44: 				active = append(active, i)
45: 			}
46: 		}
47: 		if weightTotal <= 0 {
48: 			return nil, false
49: 		}
50: 		shares := make([]quotaShare, 0, len(active))
51: 		used := 0
52: 		for _, i := range active {
53: 			request := requests[i]
54: 			numerator := int64(left) * int64(request.Weight)
55: 			whole := int(numerator / weightTotal)
56: 			room := request.Max - out[request.ID]
57: 			if whole > room {
58: 				whole = room
59: 			}
60: 			shares = append(shares, quotaShare{i, whole, numerator % weightTotal})
61: 			used += whole
62: 		}
63: 		for _, share := range shares {
64: 			out[requests[share.index].ID] += share.whole
65: 		}
66: 		left -= used
67: 		if left == 0 {
68: 			break
69: 		}
70: 		sort.SliceStable(shares, func(i, j int) bool {
71: 			if shares[i].remainder == shares[j].remainder {
72: 				return shares[i].index < shares[j].index
73: 			}
74: 			return shares[i].remainder > shares[j].remainder
75: 		})
76: 		progressed := false
77: 		for _, share := range shares {
78: 			id := requests[share.index].ID
79: 			if left > 0 && out[id] < requests[share.index].Max {
80: 				out[id]++
81: 				left--
82: 				progressed = true
83: 			}
84: 		}
85: 		if !progressed {
86: 			return nil, false
87: 		}
88: 	}
89: 	return out, true
90: }

file_sha256:1a91e8b1333f29531635944ee06f339110e8c0a8b2adfcdf11fc6b2980759330
1: package repair
2: 
3: import (
4: 	"reflect"
5: 	"testing"
6: )
7: 
8: func TestAllocateQuota(t *testing.T) {
9: 	requests := []Request{{"a", 1, 10, 1}, {"b", 1, 10, 2}, {"c", 0, 10, 1}}
10: 	if got, ok := AllocateQuota(10, requests); !ok || !reflect.DeepEqual(got, map[string]int{"a": 3, "b": 5, "c": 2}) {
11: 		t.Fatalf("weighted=%v ok=%v", got, ok)
12: 	}
13: 	capped := []Request{{"a", 0, 1, 100}, {"b", 0, 9, 1}}
14: 	if got, ok := AllocateQuota(5, capped); !ok || !reflect.DeepEqual(got, map[string]int{"a": 1, "b": 4}) {
15: 		t.Fatalf("capped=%v ok=%v", got, ok)
16: 	}
17: 	tied := []Request{{"b", 0, 2, 1}, {"a", 0, 2, 1}}
18: 	if got, ok := AllocateQuota(1, tied); !ok || got["a"] != 1 {
19: 		t.Fatalf("tie=%v ok=%v", got, ok)
20: 	}
21: 	for _, bad := range [][]Request{{{"x", 2, 1, 1}}, {{"x", 0, 1, 0}}, {{"x", 0, 1, 1}, {"x", 0, 1, 1}}} {
22: 		if got, ok := AllocateQuota(1, bad); ok || got != nil {
23: 			t.Fatalf("accepted %v: %v", bad, got)
24: 		}
25: 	}
26: 	if _, ok := AllocateQuota(3, []Request{{"x", 1, 2, 1}}); ok {
27: 		t.Fatal("infeasible capacity accepted")
28: 	}
29: }

